<?php require_once __DIR__.'/config/database.php';if(isset($_SESSION['user'])){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("SELECT * FROM users WHERE username=? AND status=1");$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user']=$u;header('Location:index.php');exit;}$error='Username atau password salah.';}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login - Apotek Cashflow</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#12372a}.box{max-width:420px;margin:10vh auto}</style></head><body><div class="box card shadow p-4"><h3 class="text-center">💰 Apotek Cashflow</h3><p class="text-center text-muted">Pemasukan & Pengeluaran</p><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><form method="post"><input name="username" class="form-control mb-3" placeholder="Username" required><input type="password" name="password" class="form-control mb-3" placeholder="Password" required><button class="btn btn-success w-100">Login</button></form><div class="text-center mt-3">Belum punya akun? <a href="register.php">Daftar</a></div><small class="text-muted d-block text-center mt-3">admin / admin123</small></div></body></html>